#include <stdio.h>

static long cmp_count = 0;
static int max_depth = 0;

void swap(int *x, int *y) { int t = *x; *x = *y; *y = t; }

/* 三数取中：把 首/中/尾 的中位数放到首位置，作为枢轴 */
void median3(int a[], int lo, int hi) {
    int mid = lo + (hi - lo) / 2;
    if (a[mid] < a[lo]) swap(&a[mid], &a[lo]);
    if (a[hi]  < a[lo]) swap(&a[hi],  &a[lo]);
    if (a[hi]  < a[mid]) swap(&a[hi], &a[mid]);
    swap(&a[mid], &a[lo]);          /* 中位数就位 */
}

int partition(int a[], int lo, int hi) {
    median3(a, lo, hi);
    int pivot = a[lo];
    int i = lo, j = hi;
    while (i < j) {
        while (i < j) { cmp_count++; if (a[j] < pivot) break; j--; }
        if (i < j) a[i++] = a[j];
        while (i < j) { cmp_count++; if (a[i] > pivot) break; i++; }
        if (i < j) a[j--] = a[i];
    }
    a[i] = pivot;
    return i;
}

void quick_sort(int a[], int lo, int hi, int depth) {
    if (depth > max_depth) max_depth = depth;
    if (lo >= hi) return;
    int p = partition(a, lo, hi);
    quick_sort(a, lo, p - 1, depth + 1);
    quick_sort(a, p + 1, hi, depth + 1);
}

int main(void) {
    int a[] = {49, 38, 65, 97, 76, 13, 27, 49};
    int n = (int)(sizeof(a) / sizeof(a[0]));

    printf("原始序列:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");

    quick_sort(a, 0, n - 1, 1);

    printf("排序结果:");
    for (int i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
    printf("比较次数 = %ld\n", cmp_count);
    printf("最大递归深度 = %d (理论下界 ceil(log2(n)) = 3)\n", max_depth);
    printf("结论: 三数取中使划分接近平衡，递归深度贴近 log2(n)，比较次数贴近 1.386*n*log2(n)\n");
    return 0;
}
